const agentItem = $('Agente Principal').first();
const native    = agentItem.metadata?.tokenUsage ?? {};

// El output final del agente está en el JSON (puede traer markdown fences)
const raw   = agentItem.json.output ?? '';
const clean = raw.replace(/^```json\\\\s*/i, '').replace(/\\\\s*```\\\\s*$/i, '').trim();

let parsed = {};
try { parsed = JSON.parse(clean); } catch { parsed = {}; }

const now = Date.now();
return {
  process_id:        $execution.id,
  model_name:        'gpt-5.1',
  prompt_tokens:     native.promptTokens     ?? 0,
  completion_tokens: native.completionTokens ?? 0,
  total_tokens:      native.totalTokens      ?? 0,
  ai_response:       parsed.replyText        ?? clean,
  completed_at:      now,
  created_at:        now,
  environment:       $('Convertir Entrada').item.json.environment ?? 'prod',
  token_source:      'native'
}

// 1. Obtenemos el texto del agente
let rawOutput = $('Agente Principal').item.json.output;
let data = {};

if (typeof rawOutput === 'string') {
    try {
        // Limpiamos el texto de espacios o saltos de línea al inicio/fin
        let cleanedOutput = rawOutput.trim();

        // Extraemos estrictamente lo que hay entre la primera '{' y la última '}'
        const jsonMatch = cleanedOutput.match(/\{[\s\S]*\}/);

        if (jsonMatch) {
            // Si el agente mandó un JSON correctamente, lo extraemos y lo convertimos
            cleanedOutput = jsonMatch[0];
            data = JSON.parse(cleanedOutput);
        } else {
            // PLAN B: Si no hay llaves, significa que mandó texto puro. 
            // Lo metemos directamente en replyText.
            data = { replyText: cleanedOutput };
        }

    } catch (error) {
        // PLAN C: Si intentó parsear un JSON pero estaba roto, salvamos el mensaje original.
        console.error("Error al parsear el JSON:", error);
        data = { replyText: rawOutput }; 
    }
} else {
    // Si ya venía como objeto, lo asignamos directamente
    data = rawOutput || {};
}

// 2. Obtenemos la lista plana de productos que viene en el input
let rawCatalog = [];
if (data.catalog){
  rawCatalog = Array.isArray(data.catalog) ? data.catalog : [data.catalog];
}

// 3. Retornamos el objeto final
return {
  replyText: data.replyText || "",
  sendImage: !!data.sendImage,
  imagenproducto: !!data.imagenproducto,
  catalog: rawCatalog
};

// Arma la lista de imágenes a enviar con las URLs que vienen de Qdrant.
// - Varios productos (ej. "¿tienes coches?"): 1 imagen por producto, máx. 5.
// - Un solo producto: 1 imagen por color (variant_image_url; si el color no tiene, usa main_image_url).
//   Si varios colores comparten la misma imagen, se envía una vez con los colores juntos en el caption.
const catalog = $('Poner formato necesario').first().json.catalog || [];
const MAX_PRODUCTOS = 5;
const MAX_COLORES = 10;

// Junta productos de todas las categorías, sin repetidos
const vistos = new Set();
const productos = [];
for (const cat of catalog) {
  for (const p of (cat.productos || [])) {
    const titulo = (p.titulo || '').trim();
    if (!titulo || vistos.has(titulo)) continue;
    vistos.add(titulo);
    productos.push({ ...p, titulo });
  }
}

const salida = [];

if (productos.length === 1) {
  // Un solo producto -> una imagen por color
  const p = productos[0];
  const colores = (p.colores || []).slice(0, MAX_COLORES);
  const porUrl = new Map();   // imageUrl -> [colores]
  const sinImagen = [];

  for (const c of colores) {
    const url = c.variant_image_url || p.main_image_url || null;
    const color = (c.color || '').trim();
    if (!url) { sinImagen.push(color); continue; }
    if (!porUrl.has(url)) porUrl.set(url, []);
    if (color) porUrl.get(url).push(color);
  }

  for (const [imageUrl, cols] of porUrl) {
    const titulo = cols.length ? `${p.titulo} (${cols.join(' / ')})` : p.titulo;
    salida.push({ json: { titulo, imageUrl } });
  }
  if (sinImagen.length || colores.length === 0 && !p.main_image_url) {
    const cols = sinImagen.filter(Boolean);
    const titulo = cols.length ? `${p.titulo} (${cols.join(' / ')})` : p.titulo;
    salida.push({ json: { titulo, imageUrl: null } });
  }
  if (colores.length === 0 && p.main_image_url) {
    salida.push({ json: { titulo: p.titulo, imageUrl: p.main_image_url } });
  }
} else {
  // Varios productos -> una imagen por producto
  for (const p of productos.slice(0, MAX_PRODUCTOS)) {
    const colores = p.colores || [];
    const first = colores[0] || {};
    const imageUrl = (colores.length === 1 && first.variant_image_url)
      ? first.variant_image_url
      : (p.main_image_url ?? null);
    salida.push({ json: { titulo: p.titulo, imageUrl } });
  }
}

return salida;

